pub fn basename(path : StringView) -> StringView {
  let path = match path {
    [.. path, '/'] => path
    path => path
  }
  fn scan(current : StringView) -> StringView {
    match current {
      [] => path
      [.., '/'] as view => path.view(start_offset=view.end_offset())
      [.. view, _] => scan(view)
    }
  }
  scan(path.view())
}

