pub fn basename(path : StringView) -> StringView {
  let trimmed = path.trim_end(chars="/")
  if trimmed.is_empty() {
    return if path.is_empty() { path } else { path.view(end_offset=1) }
  }
  match trimmed.rev_find("/") {
    None => trimmed
    Some(index) => trimmed.view(start_offset=index + 1)
  }
}

